package org.apache.camel.language.simple.types;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * Types of binary operators supported
 */
public enum BinaryOperatorType {

    EQ,
    EQ_IGNORE,
    GT,
    GTE,
    LT,
    LTE,
    NOT_EQ,
    NOT_EQ_IGNORE,
    CONTAINS,
    NOT_CONTAINS,
    CONTAINS_IGNORECASE,
    NOT_CONTAINS_IGNORECASE,
    REGEX,
    NOT_REGEX,
    IN,
    NOT_IN,
    IS,
    NOT_IS,
    RANGE,
    NOT_RANGE,
    STARTS_WITH,
    NOT_STARTS_WITH,
    ENDS_WITH,
    NOT_ENDS_WITH,
    EQUALS,
    NOT_EQUALS;

    private static final Logger LOG = LoggerFactory.getLogger(BinaryOperatorType.class);

    public static BinaryOperatorType asOperator(String text) {
        if ("==".equals(text)) {
            return EQ;
        } else if ("=~".equals(text)) {
            return EQ_IGNORE;
        } else if (">".equals(text)) {
            return GT;
        } else if (">=".equals(text)) {
            return GTE;
        } else if ("<".equals(text)) {
            return LT;
        } else if ("<=".equals(text)) {
            return LTE;
        } else if ("!=".equals(text)) {
            return NOT_EQ;
        } else if ("!=~".equals(text)) {
            return NOT_EQ_IGNORE;
        } else if ("contains".equals(text)) {
            return CONTAINS;
        } else if ("!contains".equals(text)) {
            return NOT_CONTAINS;
        } else if ("not contains".equals(text)) {
            LOG.warn("Simple operator `not contains` is deprecated, use `!contains` instead");
            return NOT_CONTAINS;
        } else if ("~~".equals(text)) {
            return CONTAINS_IGNORECASE;
        } else if ("!~~".equals(text)) {
            return NOT_CONTAINS_IGNORECASE;
        } else if ("regex".equals(text)) {
            return REGEX;
        } else if ("!regex".equals(text)) {
            return NOT_REGEX;
        } else if ("not regex".equals(text)) {
            LOG.warn("Simple operator `not regex` is deprecated, use `!regex` instead");
            return NOT_REGEX;
        } else if ("in".equals(text)) {
            return IN;
        } else if ("!in".equals(text)) {
            return NOT_IN;
        } else if ("not in".equals(text)) {
            LOG.warn("Simple operator `not in` is deprecated, use `!in` instead");
            return NOT_IN;
        } else if ("is".equals(text)) {
            return IS;
        } else if ("!is".equals(text)) {
            return NOT_IS;
        } else if ("not is".equals(text)) {
            LOG.warn("Simple operator `not is` is deprecated, use `!is` instead");
            return NOT_IS;
        } else if ("range".equals(text)) {
            return RANGE;
        } else if ("!range".equals(text)) {
            return NOT_RANGE;
        } else if ("not range".equals(text)) {
            LOG.warn("Simple operator `not range` is deprecated, use `!range` instead");
            return NOT_RANGE;
        } else if ("startsWith".equals(text)) {
            return STARTS_WITH;
        } else if ("starts with".equals(text)) {
            LOG.warn("Simple operator `starts with` is deprecated, use `startsWith` instead");
            return STARTS_WITH;
        } else if ("endsWith".equals(text)) {
            return ENDS_WITH;
        } else if ("ends with".equals(text)) {
            LOG.warn("Simple operator `ends with` is deprecated, use `endsWith` instead");
            return ENDS_WITH;
        } else if ("!startsWith".equals(text)) {
            return NOT_STARTS_WITH;
        } else if ("!endsWith".equals(text)) {
            return NOT_ENDS_WITH;
        } else if ("equals".equals(text)) {
            return EQUALS;
        } else if ("!equals".equals(text)) {
            return NOT_EQUALS;
        }
        throw new IllegalArgumentException("Operator not supported: " + text);
    }

    public static String getOperatorText(BinaryOperatorType operator) {
        if (operator == EQ) {
            return "==";
        } else if (operator == EQ_IGNORE) {
            return "=~";
        } else if (operator == GT) {
            return ">";
        } else if (operator == GTE) {
            return ">=";
        } else if (operator == LT) {
            return "<";
        } else if (operator == LTE) {
            return "<=";
        } else if (operator == NOT_EQ) {
            return "!=";
        } else if (operator == NOT_EQ_IGNORE) {
            return "!=~";
        } else if (operator == CONTAINS) {
            return "contains";
        } else if (operator == NOT_CONTAINS) {
            return "!contains";
        } else if (operator == CONTAINS_IGNORECASE) {
            return "~~";
        } else if (operator == NOT_CONTAINS_IGNORECASE) {
            return "!~~";
        } else if (operator == REGEX) {
            return "regex";
        } else if (operator == NOT_REGEX) {
            return "!regex";
        } else if (operator == IN) {
            return "in";
        } else if (operator == NOT_IN) {
            return "!in";
        } else if (operator == IS) {
            return "is";
        } else if (operator == NOT_IS) {
            return "!is";
